(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["microbiology-exam-2"]={"title":"Microbiology Exam 2","sections":[{"id":"l7-scope","title":"L7 · What the Lecturer Flagged","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-types","title":"L7 · Immunopathologies & the Four Hypersensitivities","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-allergy","title":"L7 · Type I in Detail, Diagnosis & Management","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-transfusion","title":"L7 · Transfusion Reactions & Rh","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-transplant","title":"L7 · Transplantation & Histocompatibility","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-auto-deficiency","title":"L7 · Autoimmunity & Immunodeficiency","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l7-cancer","title":"L7 · Carcinogenesis & Immunotherapy","style":"--acc:#1f4d2b;--acc-bg:#e0e6e1;--acc-zebra:#eff3f0;--acc-ink:#183c22"},{"id":"l8-categories","title":"L8 · Diagnosing Infections: The Three Categories","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l8-phenotypic","title":"L8 · Phenotypic Methods & Sensitivity Testing","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"},{"id":"l8-genotypic-immuno","title":"L8 · Genotypic & Immunological Methods","style":"--acc:#3f8a55;--acc-bg:#e4efe7;--acc-zebra:#f2f7f3;--acc-ink:#316c42"}],"rows":[{"t":"★ Learn this table","d":"The four-hypersensitivity summary table (slide 9): “a chart you should pay attention to.”","s":0},{"t":"★ The one mechanism","d":"Desensitization works by raising allergen-specific immunoglobulin G that BLOCKS the allergen from the immunoglobulin E on mast cells.","s":0},{"t":"★ No type I","d":"Type I plays NO part in graft rejection or in autoimmunity. Both use II, III and IV.","s":0},{"t":"★ B cell vs T cell defect","d":"B cell defect (agammaglobulinemia) → recurrent BACTERIAL infections. T cell defect → fungal, viral, protozoan.","s":0},{"t":"Not to memorize","d":"Helminth-allergen pairings (slide 6) · graft versus host grades (slide 50) · autoimmune disease charts (slides 58–60) · the order of the transformation sequence (slide 67). Oncogenic virus table (slide 68) deferred to the virus lectures.","s":0},{"t":"Four immunopathologies","d":"OVER: allergy/hypersensitivity, autoimmunity (typically). UNDER: immunodeficiency, cancer (both a cause and an effect of immune dysfunction).","s":1},{"t":"Hypersensitivity","d":"Exaggerated, misdirected response to an allergen using the SAME mechanisms as protective immunity. I, II, III = B cell mediated; IV = T cell mediated.","s":1},{"t":"Type I","d":"IMMEDIATE. Immunoglobulin E on mast cells, basophils, eosinophils is crosslinked → mediators. Hay fever, hives, anaphylactic shock.","s":1},{"t":"Type II","d":"Immunoglobulin G/M against CELL SURFACE antigen → complement, lysis by membrane attack complex, phagocytosis. Transfusion reactions, Rh disease, autoimmune hemolytic anemia, myasthenia gravis.","s":1},{"t":"Type III","d":"Immunoglobulin G/M against SOLUBLE antigen → immune complexes in basement membranes. Needs lots of antigen; delayed hours to days; joints, skin, kidney. Serum sickness, Arthus reaction, post-streptococcal glomerulonephritis, lupus, rheumatoid arthritis.","s":1},{"t":"Type IV","d":"DELAYED, T cell mediated. Infectious allergy (tuberculosis, leprosy, syphilis, histoplasmosis, toxoplasmosis, candidiasis), tuberculin test, contact dermatitis, graft rejection.","s":1},{"t":"Hygiene hypothesis","d":"Helminths give the allergic profile without allergy: nonspecific immunoglobulin E crowds Fc receptors and regulatory T cells suppress. Remove the worms and the immune system is underused and poorly regulated.","s":1},{"t":"Asthma crosses types","d":"Acute = type I (bronchospasm, mucus). Chronic = TYPE IV (cytokines, eosinophil granules).","s":1},{"t":"Sensitizing vs provocative dose","d":"FIRST contact: immunoglobulin E made and parked on mast cells, no symptoms. LATER contact: allergen crosslinks it → degranulation. 10,000–40,000 immunoglobulin E per cell.","s":2},{"t":"Skin","d":"Urticaria = skin mast cells + histamine. Angioedema = DEEPER mast cells. Eczema = PROLONGED response. Food urticaria: antigen carried to the skin in blood.","s":2},{"t":"Anaphylaxis","d":"Cutaneous = wheal and flare (used in diagnosis). Systemic = fluid leaves blood → pressure falls → swelling → asphyxiation. 500–1000 deaths a year in the United States.","s":2},{"t":"Epinephrine (5 actions)","d":"Reseals endothelial tight junctions · relaxes bronchi · reduces airway mucosal edema · stimulates heart · suppresses histamine release.","s":2},{"t":"Late phase","d":"About 6 HOURS after the immediate reaction; synthesized mediators such as leukotrienes; eosinophils; tissue more sensitive next time.","s":2},{"t":"Diagnosis","d":"Allergy or infection? Skin prick/intradermal (wheal and flare) · blood: specific immunoglobulin E, basophils · supervised food challenge · PATCH test = contact dermatitis (type IV).","s":2},{"t":"Drugs","d":"Corticosteroids ↓ immunoglobulin E via lymphocytes · cromolyn blocks degranulation · montelukast blocks leukotriene synthesis · omalizumab = anti-immunoglobulin E antibody · antihistamines block receptors.","s":2},{"t":"Desensitization","d":"Subcutaneous immunotherapy most common; ~80% improve. Also regulatory T cells. Sublingual: under the tongue; peanut dose 1/75 of a kernel.","s":2},{"t":"Why ABO","d":"Red cells carry NO major histocompatibility complex molecules. You make antibody against the ABO antigens you LACK.","s":3},{"t":"Cross-match","d":"RECIPIENT serum against DONOR red cells — never the reverse (too little donor antibody to react).","s":3},{"t":"Consequences","d":"Complement lysis → blocked glomeruli, fever, jaundice; coated cells also cleared by natural killer cells and macrophages.","s":3},{"t":"Rh disease","d":"Rh-negative mother, Rh-positive fetus. First pregnancy sensitizes; later ones hemolytic (erythroblastosis fetalis).","s":3},{"t":"Rhogam timing","d":"Passive anti-Rh antibody prevents sensitization. 26–28 WEEKS · within 72 HOURS of birth · after invasive tests, abdominal injury, accidental exposure.","s":3},{"t":"Graft types","d":"Autograft = self · isograft = identical twin · allograft = same species · xenograft = other species.","s":4},{"t":"★ Rejection by type","d":"Hyperacute = II (preexisting antibody; engorged, purple graft) · acute = IV (T cells vs human leukocyte antigen differences) · chronic = III (thickened vessel walls) · graft versus host = IV.","s":4},{"t":"Chronic rejection","d":"Months to years; fails MORE THAN HALF of kidney and heart transplants after 10+ years.","s":4},{"t":"Acute rejection route","d":"Graft dendritic cells → SPLEEN → activate effector T cells → back via blood → graft destroyed.","s":4},{"t":"Cornea","d":"First organ transplanted; succeeds WITHOUT a human leukocyte antigen match — eye downregulates T cells, macrophages, neutrophils, complement.","s":4},{"t":"Liver","d":"Human leukocyte antigens NOT assessed; ABO IS. Hepatocytes: little class I, no class II.","s":4},{"t":"Bone marrow","d":"MOST sensitive to mismatch → graft versus host disease (skin, muscle, liver, gut) in ~30%.","s":4},{"t":"Preventing rejection","d":"Tissue typing, mixed lymphocyte reaction; purine analogs, corticosteroids, tacrolimus, cyclosporine, rapamycin (sirolimus).","s":4},{"t":"Autoimmunity","d":"Lost tolerance → autoantibodies and sensitized T cells. All types EXCEPT I. Runs in families; WOMEN more often.","s":5},{"t":"Sequestered antigen","d":"Privileged tissue (central nervous system, lens, thyroid, testes) damaged later releases unseen antigen. One injured eye → T cells attack BOTH.","s":5},{"t":"Molecular mimicry","d":"Rheumatic fever (strep → heart) · Lyme arthritis (Borrelia) · reactive arthritis (Shigella, Salmonella, Campylobacter) · type 1 diabetes (coxsackie A/B, echovirus, rubella).","s":5},{"t":"Thymic senescence","d":"Thymus involutes to fat; premature aging in young people with autoimmunity; less output → infection, cancer, autoimmunity.","s":5},{"t":"Slide 61 diseases","d":"Graves' (stimulates follicle cells → hyper) · Hashimoto's (destroys them → hypo) · myasthenia gravis (acetylcholine receptors) · multiple sclerosis (myelin; T cells + antibody; Epstein-Barr link).","s":5},{"t":"Primary vs secondary","d":"PRIMARY = congenital, genetic. SECONDARY = acquired after birth: human immunodeficiency virus (T helper cells), chemotherapy, radiation, blood cell cancers.","s":5},{"t":"Primary examples","d":"Agammaglobulinemia (B, no antibody) · DiGeorge (T, no thymus) · severe combined immunodeficiency (both limbs, no adaptive response) · complement, phagocyte defects.","s":5},{"t":"Transformation","d":"ONE cell with MULTIPLE accumulated mutations; oncogenes activated by radiation, chemicals, oncogenic viruses. Benign = contained; malignant = spreads.","s":6},{"t":"Cancer cell traits","d":"Self-stimulating · ignore stop signals · no apoptosis · angiogenesis · metastasis · constant replication · evade immunity.","s":6},{"t":"Tumor antigens","d":"SPECIFIC = tumor only. ASSOCIATED = tumor + normal cells (less).","s":6},{"t":"Evasion","d":"Shed the natural killer stress ligand · secrete transforming growth factor beta → regulatory T cells (+ interleukin 10). More regulatory T cells = WORSE prognosis.","s":6},{"t":"Checkpoint inhibitors","d":"Block the T cell OFF signal; do not kill directly. Melanoma, some lung cancers.","s":6},{"t":"Adoptive cell therapy","d":"Patient's cells engineered and returned. CAR-T (chimeric antigen receptor T cells) APPROVED for blood cancers; tumor infiltrating lymphocytes in development; chimeric antigen receptor natural killer cells in trials.","s":6},{"t":"Antibodies & cytokines","d":"100+ monoclonal antibodies, diagnosis AND therapy; conjugates carry drug or radionuclide. Interleukin 2 → T and natural killer cells (kidney, melanoma). Interferon alpha → natural killer and dendritic cells. Erythropoietin = red cells; interleukin 11 = platelets.","s":6},{"t":"Coley · viruses · vaccines","d":"Coley's toxins (1890s; killed strep + Serratia; displaced by radiation and chemotherapy). Oncolytic viruses replicate only in tumor cells; mumps natural. Prophylactic: hepatitis B, papillomavirus. Therapeutic: bacillus Calmette-Guérin (bladder), sipuleucel-T (prostate).","s":6},{"t":"Scope note","d":"The objectives are the course-wide list; the lecture teaches diagnostic METHODS. Sort every technique into one of three.","s":7},{"t":"Phenotypic","d":"Observable traits (phenotype = physical expression of genes): morphology, biochemistry, chemistry, drug sensitivity. Needs culture → SLOWER.","s":7},{"t":"Genotypic","d":"Genetic makeup; NO culture needed — slow Mycobacterium, hard Legionella. Faster diagnosis → timely treatment.","s":7},{"t":"Immunological","d":"Antigen-antibody specificity; culture optional. Rapid strep 10–15 minutes, but you need a hypothesis first.","s":7},{"t":"Specimens","d":"ALL potentially infectious. Results depend on collection, handling, transport, storage. Universal precautions MITIGATE, not eliminate.","s":7},{"t":"Results","d":"Direct tests or culture-isolation-identification; results PRESUMPTIVE or CONFIRMATORY.","s":7},{"t":"Morphology","d":"Microscopic: shape, size, stain (Gram, flagellar, acid-fast), structures. Macroscopic: colony texture, size, shape, pigment.","s":8},{"t":"Biochemical","d":"Presence or absence of enzymes/pathways: fermentation, amino acids, hydrolysis, catalase, oxidase, coagulase, hemolysins.","s":8},{"t":"★ Blood agar","d":"Detects HEMOLYSIS — the lecturer's “take-home message”, especially for pathogenic Gram-positives.","s":8},{"t":"Other media","d":"Chocolate agar: “mainly anaerobic culturing” (slide's wording) · mannitol salts: selects salt tolerance, differentiates mannitol · citrate: blue = pH up · urea: hot pink = urease.","s":8},{"t":"Normal flora?","d":"Is the recovered organism the cause, or normal flora? Koch's postulates reasoning.","s":8},{"t":"Kirby-Bauer","d":"Disk diffusion: WHICH drug and at WHAT dose; LARGER zone = more effective. Minimum inhibitory concentration strips give the concentration.","s":8},{"t":"Polymerase chain reaction","d":"Thermal cycler amplifies nucleic acid; Kary Mullis. Guanine + cytosine content = taxonomy, not specific identification.","s":9},{"t":"Ribosomal ribonucleic acid","d":"16S for bacteria, 18S for eukaryotes → phylogenetic trees. Restriction fragment length polymorphism = “fingerprinting.”","s":9},{"t":"Serology","d":"In vitro testing of serum; titer in binding antibody units. Serotyping = known antibody identifies an unknown microbe.","s":9},{"t":"Agglutination vs precipitation","d":"Agglutination = WHOLE-CELL/insoluble antigen, clumps, MORE sensitive (blood typing, syphilis, Weil-Felix, pregnancy, rapid strep). Precipitation = SOLUBLE antigen, needs gel/liquid (Ouchterlony, immunoelectrophoresis → antibody class).","s":9},{"t":"Blots","d":"Southern = deoxyribonucleic acid (the man's name) · Northern = ribonucleic acid · WESTERN = PROTEIN, second test for human immunodeficiency virus · Eastern = other epitopes.","s":9},{"t":"Complement fixation","d":"4 parts: antigen, antibody, complement, sheep red cells. NO hemolysis = POSITIVE. Hemolysis = negative.","s":9},{"t":"Fluorescent · immunoassay · in vivo","d":"Dye-labeled monoclonal antibody, direct or indirect. Immunoassays detect TRACE amounts (radioimmunoassay; enzyme-linked immunosorbent assay, 96-well). In vivo: tuberculin, allergy tests.","s":9},{"t":"Viruses","d":"Not cells; need a host cell → labor intensive to culture; rapid antigen-antibody tests.","s":9}],"map":{"microbiology-exam-2-diagnosing-infections-quiz-version-2":[-1,64,65,-1,54,56,67,59,50,60,60,50,51,56,-1,-1,-1,68,51,52,-1,63,52,-1,-1,58,61,55,55,66],"microbiology-exam-2-diagnosing-infections-quiz":[67,52,53,66,-1,64,50,63,64,51,63,60,58,61,66,-1,53,52,58,64,-1,-1,58,62,64,-1,-1,53,64,-1],"microbiology-exam-2-disorders-in-immunity-quiz-version-2":[24,6,43,33,12,-1,46,-1,12,5,27,29,26,14,21,38,-1,39,45,9,32,39,-1,41,-1,41,21,43,6,34],"microbiology-exam-2-disorders-in-immunity-quiz":[21,34,36,10,3,2,-1,-1,26,23,6,6,37,45,11,2,2,-1,1,-1,-1,3,-1,5,36,11,36,44,39,26]}};
